H.background();
const ord = Math.round(P.order);
const k = 0.4, A0 = 2.0;
const tEnd = 5;
const v = H.plot2d({ xMin: 0, xMax: tEnd, yMin: -1, yMax: 4 });
v.grid(); v.axes();
function conc(tt) {
  if (ord === 0) return Math.max(A0 - k * tt, 0.001);
  if (ord === 2) return 1 / (1 / A0 + k * tt);
  return A0 * Math.exp(-k * tt);
}
const yLabel = ord === 0 ? "[A]" : ord === 1 ? "ln[A]" : "1/[A]";
function transform(tt) {
  const c = conc(tt);
  if (ord === 0) return c;
  if (ord === 1) return Math.log(c);
  return 1 / c;
}
v.fn(x => transform(x), { color: H.colors.good, width: 3 });
const sweep = (t % 5) / 5 * tEnd;
v.dot(sweep, transform(sweep), { r: 7, fill: H.colors.accent2 });
H.text("Find order: which plot is a straight line?", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Order " + ord + " is LINEAR when you plot  " + yLabel + "  vs  t", 24, 52, { color: H.colors.sub, size: 13 });
H.text("0th: [A] linear   |   1st: ln[A] linear   |   2nd: 1/[A] linear", 24, 80, { color: H.colors.sub, size: 13 });
H.text("plotting " + yLabel + " vs t,  slope = " + (ord === 0 ? "-k" : ord === 1 ? "-k" : "+k"), 24, 98, { color: H.colors.good, size: 13 });
H.text("t = " + sweep.toFixed(2) + " s,  " + yLabel + " = " + transform(sweep).toFixed(2), 24, 116, { color: H.colors.accent2, size: 13 });
